def solve(size):
    # Knight moves
    knight_moves = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]

    def valid(r, c):
        return 0 <= r < size and 0 <= c < size

    # BFS/DFS to find all squares reachable in exactly 3 moves
    # We track positions reachable at each step
    # Start at (0,0)

    # Use sets for each step
    # But we need "exactly 3 moves" - so we do BFS level by level
    # At each level, we track all reachable positions (with possible revisits)
    # We want squares reachable at step 3

    # Since we want SQUARES (not paths), we track the set of positions reachable
    # at exactly step k (the knight can be at those positions after k moves)

    # Step 0: {(0,0)}
    # Step k+1: all valid positions reachable from step k positions

    current = {(0, 0)}

    for step in range(3):
        next_positions = set()
        for (r, c) in current:
            for (dr, dc) in knight_moves:
                nr, nc = r + dr, c + dc
                if valid(nr, nc):
                    next_positions.add((nr, nc))
        current = next_positions

    # Top-left square color: (0+0) % 2 = 0 (even)
    # Opposite color: odd (r+c) % 2 == 1
    # But as analyzed, all squares after 3 moves have opposite color
    # Still, let's filter for opposite color squares
    top_left_color = (0 + 0) % 2  # 0
    opposite_color = 1 - top_left_color  # 1

    opposite_squares = {(r,c) for (r,c) in current if (r+c) % 2 == opposite_color}

    return len(opposite_squares)

