import random

def solve(degree, range_coeff):
    """
    Generate a random polynomial function of given degree with coefficients
    in the range [-range_coeff, range_coeff].

    Args:
        degree: The degree of the polynomial
        range_coeff: The range for coefficients (-range_coeff to range_coeff)

    Returns:
        A string representation of the polynomial function
    """
    # Generate random coefficients for each term
    # We need degree+1 coefficients (from x^degree down to x^0)
    coefficients = []
    for i in range(degree + 1):
        coeff = random.randint(-range_coeff, range_coeff)
        coefficients.append(coeff)

    # Make sure the leading coefficient is not zero
    while coefficients[0] == 0:
        coefficients[0] = random.randint(-range_coeff, range_coeff)

    # Build the polynomial string
    terms = []
    for i, coeff in enumerate(coefficients):
        power = degree - i

        if coeff == 0:
            continue

        if power == 0:
            terms.append(f"{coeff}")
        elif power == 1:
            if coeff == 1:
                terms.append("x")
            elif coeff == -1:
                terms.append("-x")
            else:
                terms.append(f"{coeff}x")
        else:
            if coeff == 1:
                terms.append(f"x^{power}")
            elif coeff == -1:
                terms.append(f"-x^{power}")
            else:
                terms.append(f"{coeff}x^{power}")

    if not terms:
        return "f(x) = 0"

    # Join terms with proper signs
    polynomial = terms[0]
    for term in terms[1:]:
        if term.startswith('-'):
            polynomial += f" - {term[1:]}"
        else:
            polynomial += f" + {term}"

    return f"f(x) = {polynomial}"

